  "sql": "WITH base AS (\n  SELECT\n    DATE_TRUNC('MONTH', orders.order_date) AS \"orders.order_date\",\n    CAST(SUM(orders.amount) AS DOUBLE) AS \"orders.revenue\"\n  FROM orders AS orders\n  LEFT JOIN customers AS customers\n    ON orders.customer_id = customers.id\n  WHERE\n    (\n      orders.order_date >= CAST('2025-01-01' AS DATE)\n      AND orders.order_date < CAST('2026-01-01' AS DATE)\n    )\n    AND CASE\n      WHEN customers.tags IS NULL OR 'vip' IS NULL\n      THEN NULL\n      ELSE LIST_CONTAINS([__slayer_e FOR __slayer_e IN customers.tags IF __slayer_e IS NOT NULL], 'vip')\n    END\n  GROUP BY\n    DATE_TRUNC('MONTH', orders.order_date)\n), shifted__time_shift_inner AS (\n  SELECT\n    DATE_TRUNC('MONTH', orders.order_date) AS \"orders.order_date\",\n    CAST(SUM(orders.amount) AS DOUBLE) AS \"orders.revenue\"\n  FROM orders AS orders\n  LEFT JOIN customers AS customers\n    ON orders.customer_id = customers.id\n  WHERE\n    CASE\n      WHEN customers.tags IS NULL OR 'vip' IS NULL\n      THEN NULL\n      ELSE LIST_CONTAINS([__slayer_e FOR __slayer_e IN customers.tags IF __slayer_e IS NOT NULL], 'vip')\n    END\n  GROUP BY\n    DATE_TRUNC('MONTH', orders.order_date)\n), sjoin__time_shift_inner AS (\n  SELECT\n    base.\"orders.order_date\",\n    base.\"orders.revenue\",\n    shifted__time_shift_inner.\"orders.revenue\" AS \"orders._time_shift_inner\"\n  FROM base\n  LEFT JOIN shifted__time_shift_inner\n    ON base.\"orders.order_date\" - INTERVAL 1 MONTH IS NOT DISTINCT FROM shifted__time_shift_inner.\"orders.order_date\"\n), step1 AS (\n  SELECT\n    \"orders.order_date\",\n    \"orders.revenue\",\n    \"orders._time_shift_inner\",\n    \"orders.revenue\" - \"orders._time_shift_inner\" AS \"orders.change\"\n  FROM sjoin__time_shift_inner\n)\nSELECT\n  \"orders.order_date\",\n  \"orders.revenue\",\n  \"orders.change\"\nFROM (\n  SELECT\n    \"orders.order_date\",\n    \"orders.revenue\",\n    \"orders._time_shift_inner\",\n    \"orders.change\"\n  FROM step1\n) AS _outer\nORDER BY\n  \"orders.order_date\" ASC\nLIMIT 101"
